import{_ as e}from"./chunks/sh1.DiUu_JVG.js";import{_ as t,c as o,o as l,ae as n}from"./chunks/framework.BrQRMotl.js";const g=JSON.parse('{"title":"扩展音符盒基础","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/extended_note_block.md","filePath":"zh/manual/extended_note_block.md"}'),r={name:"zh/manual/extended_note_block.md"};function i(s,a,d,h,u,c){return l(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="扩展音符盒基础" tabindex="-1">扩展音符盒基础 <a class="header-anchor" href="#扩展音符盒基础" aria-label="Permalink to &quot;扩展音符盒基础&quot;">​</a></h1><p><strong>Extended Note Block</strong> 是本模组的核心。与原版音符盒相比，它提供了更精准的控制和更丰富的功能。</p><h2 id="放置与基础设置" tabindex="-1">放置与基础设置 <a class="header-anchor" href="#放置与基础设置" aria-label="Permalink to &quot;放置与基础设置&quot;">​</a></h2><ul><li><strong>放置</strong>: 像放置原版音符盒一样放置 <strong>扩展音符盒 (Extended Note Block)</strong>。</li><li><strong>打开界面</strong>: <strong>右键点击</strong> 方块即可打开其配置界面。</li></ul><p><img src="'+e+'" alt="Extended Note Block GUI"></p><h2 id="参数详解" tabindex="-1">参数详解 <a class="header-anchor" href="#参数详解" aria-label="Permalink to &quot;参数详解&quot;">​</a></h2><p>在基础设置界面中，你可以配置以下参数：</p><h3 id="_1-音高-note" tabindex="-1">1. 音高 (Note) <a class="header-anchor" href="#_1-音高-note" aria-label="Permalink to &quot;1. 音高 (Note)&quot;">​</a></h3><ul><li><strong>范围</strong>: 0 - 127 (对应 MIDI 标准)。</li><li>不同于原版的 0-24 限制，这里你可以播放横跨 10 个八度的声音。</li></ul><h3 id="_2-力度-velocity" tabindex="-1">2. 力度 (Velocity) <a class="header-anchor" href="#_2-力度-velocity" aria-label="Permalink to &quot;2. 力度 (Velocity)&quot;">​</a></h3><ul><li><strong>范围</strong>: 0 - 127。</li><li>控制声音的大小（音量）。</li></ul><h3 id="_3-延音-sustain" tabindex="-1">3. 延音 (Sustain) <a class="header-anchor" href="#_3-延音-sustain" aria-label="Permalink to &quot;3. 延音 (Sustain)&quot;">​</a></h3><ul><li><strong>单位</strong>: 刻 (Tick, 1/20秒)。</li><li>控制声波结束前的持续时间。</li></ul><h3 id="_4-播放延迟-delay" tabindex="-1">4. 播放延迟 (Delay) <a class="header-anchor" href="#_4-播放延迟-delay" aria-label="Permalink to &quot;4. 播放延迟 (Delay)&quot;">​</a></h3><ul><li><strong>单位</strong>: 毫秒 (ms)。</li><li>这是一个<strong>实时延迟</strong>设置。当红石信号激活方块时，它会等待指定的毫秒数后再发声。</li><li>这允许你进行比红石中继器（0.1s 粒度）更精细的音乐对齐。</li></ul><h3 id="_5-淡入-淡出-fade-in-out" tabindex="-1">5. 淡入/淡出 (Fade In/Out) <a class="header-anchor" href="#_5-淡入-淡出-fade-in-out" aria-label="Permalink to &quot;5. 淡入/淡出 (Fade In/Out)&quot;">​</a></h3><ul><li><strong>单位</strong>: 刻 (Tick)。</li><li>让声音平滑地出现或消失，避免生硬的切断感。</li></ul>',17)])])}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
